import { Head, Link, router, useForm } from '@inertiajs/react';
import { useEffect, useState, useMemo, type ReactNode } from 'react';
import { ArrowDownLeft, ArrowUpRight, ArrowRight, ArrowUp, ArrowDown, BarChart3, CalendarDays, ChevronLeft, ChevronRight, CircleHelp, Ellipsis, Home, Leaf, ListFilter, LogOut, Moon, Plus, Settings2, Sun, Wallet, X, PiggyBank, Pencil, Trash2, Check, SlidersHorizontal, LayoutGrid, Search, Copy, Baby } from 'lucide-react';
import { Ft, amount, months, labels, Sheet, ErrorText, MoneyInput } from '../components';
import { createTransactionId } from '../transaction-id';
import type { FinanceProps, Category, CategoryReport, Transaction } from '../types';
import Accounts, { AccountBalances, huDate, modeAt } from './Accounts';
import Loans from './Loans';
import ScopeControls from '../ScopeControls';
import ReminderSettings from '../ReminderSettings';
import SystemStatus from '../SystemStatus';
import InsightsPanel from '../InsightsPanel';
import BusinessReport from './BusinessReport';
import DataTools from '../DataTools';
import Recurring from './Recurring';
import Evening from './Evening';
import { Pockets, Investments, AnnualReport } from './PhaseFour';

const viewTitles: Record<string,string> = { business: 'Üzleti / magán riport', overview: 'Áttekintés', month: 'Havi nézet', plans: 'Tervezés', settings: 'Beállítások', annual: 'Éves összesítő', pockets: 'Zsebpénzek', investments: 'Befektetéseim · Örs', accounts: 'Számlák', loans: 'Hiteleim', recurring: 'Rendszeres tételek', evening: 'Esti rögzítés' };
const query = (p: FinanceProps) => `?year=${p.year}&month=${p.month}${p.filters.account_id?`&account_id=${p.filters.account_id}`:''}${p.filters.person?`&person=${encodeURIComponent(p.filters.person)}`:''}`;

export default function Finance(p: FinanceProps) {
    const [entry, setEntry] = useState<{ type: string; tx?: Transaction; date?: string; category?: number; loan?: number } | null>(null);
    const [more, setMore] = useState(false);
    const [dark,setDark] = useState(document.documentElement.dataset.theme === 'dark');
    const [flash, setFlash] = useState(p.flash.message);
    useEffect(() => { setFlash(p.flash.message); }, [p.flash.message, p.flash.undoId]);
    const toggleTheme = () => { const next = !dark; setDark(next); document.documentElement.dataset.theme = next ? 'dark' : 'light'; try { localStorage.setItem('kassza-theme', next ? 'dark' : 'light'); } catch {} };
    const nav = [{ label:'Áttekintés', path:'/', view:'overview', icon:Home }, {label:'Hónap',path:'/honap',view:'month',icon:CalendarDays}, {label:'Éves',path:'/eves',view:'annual',icon:BarChart3}];
    const openEntry = (type='expense', date?: string, category?: number) => { setMore(false); setEntry({type,date:date??(p.view==='evening'?p.eveningDate:undefined),category}); };
    return <div className="app-shell"><Head title={viewTitles[p.view]}/>
        <aside className="sidebar"><Link href={'/'+query(p)} className="brand"><span className="brand-icon"><Leaf size={23}/></span><span>Buksza<span className="brand-sub">A MI KÖZÖS TERVÜNK</span></span></Link>
            <span className="nav-caption">A KASSZÁNK</span>{nav.map(n=><Link key={n.path} href={n.path+query(p)} className={`side-link ${p.view===n.view?'selected':''}`}><n.icon size={20}/>{n.label}</Link>)}
            <Link href={'/tervezes'+query(p)} className={`side-link ${p.view==='plans'?'selected':''}`}><SlidersHorizontal size={20}/>Tervezés</Link>
            <Link href={'/szamlak'+query(p)} className={`side-link ${p.view==='accounts'?'selected':''}`}><Wallet size={20}/>Számlák</Link>
            <Link href={'/zsebpenzek'+query(p)} className={`side-link ${p.view==='pockets'?'selected':''}`}><Wallet size={20}/>Zsebpénzek</Link>
            <Link href={'/befektetesek'+query(p)} className={`side-link ${p.view==='investments'?'selected':''}`}><Baby size={20}/>Örs babakötvényei</Link>
            <Link href={'/hitelek'+query(p)} className={`side-link ${p.view==='loans'?'selected':''}`}><PiggyBank size={20}/>Hiteleim</Link>
            <Link href={'/rendszeres'+query(p)} className={`side-link ${p.view==='recurring'?'selected':''}`}><CalendarDays size={20}/>Rendszeres tételek</Link>
            <Link href={'/uzleti-riport'+query(p)} className={`side-link ${p.view==='business'?'selected':''}`}><BarChart3 size={20}/>Üzleti / magán riport</Link>
            <Link href='/esti-rogzites' className={`side-link ${p.view==='evening'?'selected':''}`}><Check size={20}/>Esti rögzítés</Link>
            <Link href={'/beallitasok'+query(p)} className={`side-link ${p.view==='settings'?'selected':''}`}><Settings2 size={20}/>Beállítások</Link>
            <div className="sidebar-bottom"><div className="small-note"><Leaf size={19}/><p>Kis lépések.<br/><strong>Közös biztonság.</strong></p></div><button className="side-link" onClick={toggleTheme}>{dark?<Sun size={19}/>:<Moon size={19}/>} {dark?'Világos téma':'Sötét téma'}</button><button className="side-link" onClick={()=>router.post('/kilepes')}><LogOut size={19}/>Kilépés</button><div className="profile"><span>{p.auth.user.name.slice(0,1)}</span><div><strong>{p.auth.user.name}</strong><small>Családi nézet</small></div></div></div>
        </aside>
        <div className="main-shell"><header className="topbar"><Link href={'/'+query(p)} className="mobile-brand"><Leaf size={22}/>Buksza</Link><span className="desktop-breadcrumb">A kasszánk <ChevronRight size={14}/> {viewTitles[p.view]}</span><div className="top-actions"><span className="family-pill"><span className="status-dot"/>Családi nézet</span><button className="icon-button" aria-label={dark?'Világos téma':'Sötét téma'} onClick={toggleTheme}>{dark?<Sun size={20}/>:<Moon size={20}/>}</button><span className="avatar">{p.auth.user.name.slice(0,1)}</span></div></header>
            <main id="main-content" className="content"><div className="page-heading"><div><span className="eyebrow">{p.view==='overview'?'A CSALÁD PÉNZÜGYEI': 'BUKSZA'}</span><h1>{p.view==='overview'?`Szia, ${p.auth.user.name}!`:viewTitles[p.view]}</h1><p className="muted">{p.view==='overview'?'Lássuk, hogyan áll a közös kasszánk.':p.view==='month'?'A hónap minden napja, egy helyen.':p.view==='plans'?'Adj keretet a közös terveiteknek.':p.view==='business'?'A rögzített bevételek és kiadások üzleti/magán bontása.':p.view==='settings'?'A kasszád, a saját szabályaid szerint.':p.view==='accounts'?'Külön egyenlegek, közös családi kassza.':p.view==='loans'?'Minden hitel külön, a törlesztések együtt is látszanak.':p.view==='recurring'?'Saját sablonok a rendszeres pénzmozgásokhoz.':p.view==='evening'?'A napi pénzmozgások gyors, kézi rögzítése.':p.view==='pockets'?'Havi és éves zsebpénzek, személyenként.':p.view==='investments'?'Örs befizetései és MÁK-értékei, külön nyilvántartásban.':'A közös családi kassza teljes éve.'}</p></div><button className="button primary desktop-add" onClick={()=>openEntry()}><Plus size={19}/>Új kiadás</button></div>
                {!['evening','business'].includes(p.view)&&<MonthSelector p={p}/>}
                {['overview','month','recurring'].includes(p.view)&&<InsightsPanel p={p} budgets={p.view!=='recurring'} changes={p.view!=='month'}/>}
                {p.view==='business'&&<BusinessReport p={p} edit={tx=>setEntry({type:tx.type,tx})}/>}
                {p.view==='recurring'&&<Recurring p={p}/>}
                {p.view==='evening'&&<Evening key={p.eveningDate} p={p} open={openEntry} row={tx=><TransactionRow tx={tx} p={p} edit={tx=>setEntry({type:tx.type,tx})}/>}/>}
                {['overview','month','accounts'].includes(p.view)&&<ScopeControls p={p}/>}
                {p.view==='accounts'&&<Accounts p={p}/>}
                {p.view==='loans'&&<Loans p={p} repay={id=>setEntry({type:'expense',category:13,loan:id})}/>}
                {p.view==='overview'&&<Overview p={p} open={openEntry}/>}
                {p.view==='month'&&<MonthView p={p} open={openEntry} edit={tx=>setEntry({type:tx.type,tx})}/>}
                {p.view==='plans'&&<Plans p={p}/>}
                {p.view==='settings'&&<Settings p={p} toggleTheme={toggleTheme} dark={dark}/>}
                {p.view==='annual'&&<AnnualReport p={p} row={tx=><TransactionRow tx={tx} p={p} edit={tx=>setEntry({type:tx.type,tx})}/>}/>}
                {p.view==='pockets'&&<Pockets p={p} open={()=>openEntry('expense',undefined,21)}/>}
                {p.view==='investments'&&<Investments p={p} deposit={()=>openEntry('child_saving')}/>}
                <footer className="page-footer"><Leaf size={13}/> Együtt, átláthatóan. <span>Az összegek forintban értendők.</span></footer>
            </main>
        </div>
        <nav className="bottom-nav" aria-label="Fő navigáció"><Link href={'/'+query(p)} className={p.view==='overview'?'selected':''}><Home size={21}/>Áttekintés</Link><Link href={'/honap'+query(p)} className={p.view==='month'?'selected':''}><CalendarDays size={21}/>Hónap</Link><button className="quick-plus" aria-label="Új tétel" onClick={()=>openEntry()}><Plus size={26}/></button><Link href={'/eves'+query(p)} className={p.view==='annual'?'selected':''}><BarChart3 size={21}/>Éves</Link><button className={['plans','settings','accounts','loans','recurring','evening','pockets','investments','business'].includes(p.view)?'selected':''} onClick={()=>setMore(true)}><Ellipsis size={22}/>Továbbiak</button></nav>
        {entry&&<EntrySheet key={entry.tx?.id??'new'} p={p} entry={entry} close={()=>setEntry(null)}/>}
        {more&&<Sheet title="Továbbiak" close={()=>setMore(false)}><div className="more-links"><Link href={'/uzleti-riport'+query(p)} onClick={()=>setMore(false)}><BarChart3/>Üzleti / magán riport<ChevronRight/></Link><Link href={'/zsebpenzek'+query(p)} onClick={()=>setMore(false)}><Wallet/>Zsebpénzek<ChevronRight/></Link><Link href={'/befektetesek'+query(p)} onClick={()=>setMore(false)}><Baby/>Örs babakötvényei<ChevronRight/></Link><Link href='/esti-rogzites' onClick={()=>setMore(false)}><Check/>Esti rögzítés<ChevronRight/></Link><Link href={'/rendszeres'+query(p)} onClick={()=>setMore(false)}><CalendarDays/>Rendszeres tételek<ChevronRight/></Link><Link href={'/szamlak'+query(p)} onClick={()=>setMore(false)}><Wallet/>Számlák<ChevronRight/></Link><Link href={'/hitelek'+query(p)} onClick={()=>setMore(false)}><PiggyBank/>Hiteleim<ChevronRight/></Link><button onClick={()=>openEntry('transfer')}><ArrowRight/>Átvezetés rögzítése<ChevronRight/></button><Link href={'/tervezes'+query(p)} onClick={()=>setMore(false)}><SlidersHorizontal/>Tervezés<ChevronRight/></Link><Link href={'/beallitasok'+query(p)} onClick={()=>setMore(false)}><Settings2/>Beállítások<ChevronRight/></Link><button onClick={()=>openEntry('income')}><ArrowDownLeft/>Bevétel rögzítése<ChevronRight/></button><button onClick={()=>openEntry('saving')}><PiggyBank/>Félretétel rögzítése<ChevronRight/></button><button onClick={()=>openEntry('child_saving')}><Baby/>Örs befizetése<ChevronRight/></button><button onClick={()=>router.post('/kilepes')}><LogOut/>Kilépés</button></div></Sheet>}
        {flash&&<div className="toast" role="status"><Check size={19}/><span>{flash}</span>{p.flash.undoId&&<button onClick={()=>{router.post(`/tetelek/${p.flash.undoId}/visszavonas`);setFlash(undefined);}}>Visszavonás</button>}<button className="icon-button" aria-label="Üzenet bezárása" onClick={()=>setFlash(undefined)}><X size={18}/></button></div>}
    </div>;
}

function MonthSelector({p}:{p:FinanceProps}) {
    const yearOnly = p.view === 'settings' || p.view === 'annual' || p.view === 'pockets';
    const change = (year:number,month:number) => router.get(location.pathname,{year,month,...(p.filters.account_id?{account_id:p.filters.account_id}:{}),...(p.filters.person?{person:p.filters.person}:{})},{preserveScroll:true});
    const step = (delta:number) => { let year=p.year+(yearOnly?delta:0),month=p.month+(yearOnly?0:delta);if(month<1){year--;month=12;}if(month>12){year++;month=1;}if(year>=2000&&year<=2100)change(year,month); };
    return <div className="month-selector"><div className="month-picker"><CalendarDays size={18}/>{yearOnly?<span className="period-label">{p.view==='settings'?'Beállítások éve':'Összesítés éve'}</span>:<select aria-label="Hónap" value={p.month} onChange={e=>change(p.year,Number(e.target.value))}>{months.map((m,i)=><option key={m} value={i+1}>{m[0].toUpperCase()+m.slice(1)}</option>)}</select>}<select className="year-select" aria-label="Év" value={p.year} onChange={e=>change(Number(e.target.value),p.month)}>{Array.from({length:101},(_,i)=>2000+i).map(y=><option key={y}>{y}</option>)}</select></div><div className="month-arrows"><button className="icon-button" aria-label={yearOnly?'Előző év':'Előző hónap'} onClick={()=>step(-1)}><ChevronLeft size={19}/></button><button className="icon-button" aria-label={yearOnly?'Következő év':'Következő hónap'} onClick={()=>step(1)}><ChevronRight size={19}/></button></div></div>;
}
function Stat({title,value,icon,sub,className=''}:{title:string;value: Parameters<typeof Ft>[0]['value'];icon?:ReactNode;sub?:ReactNode;className?:string}) {return <div className={`stat ${className}`}><div className="stat-title">{title}{icon}</div><Ft value={value}/>{sub&&<small>{sub}</small>}</div>;}
function Empty({title,text}:{title:string;text:string}) { return <div className="empty-state"><span><Leaf size={24}/></span><h3>{title}</h3><p>{text}</p></div>; }
function Overview({p,open}:{p:FinanceProps;open:(type?:string)=>void}) {
    const r=p.report;
    const budgeted = r.categories.filter(c=>c.active||c.spent||c.plan).slice(0,6);
    const target = r.savingsTarget.value;
    const progress = target>0? Math.max(0,Math.min(100,r.actualSavings/target*100)):0;
    return <>
        {!p.transactions.length&&p.account.opening_balance===0&&<div className="onboarding"><span className="onboarding-icon"><Leaf size={22}/></span><div><strong>Kezdjük a saját számaiddal.</strong><p>Add meg a nyitóegyenleget és a havi kereteket.</p></div><Link href={'/beallitasok'+query(p)} aria-label="Kezdőadatok megadása"><ArrowRight size={20}/></Link></div>}
        <div className="balance-grid"><section className="balance-card"><div className="balance-head"><span><Wallet size={18}/>Valós számlaegyenleg</span><span className="chip">{p.account.name}</span></div>{p.account.balance === null ? <h2>Ehhez a hónaphoz nincs nyitóadat.</h2> : <Ft value={p.account.balance} className="balance-value"/>}<p>A megadott nyitóegyenleg és a rögzített pénzmozgások alapján.</p><div className="balance-foot"><span className="status-dot"/> {new Date(p.account.through+'T12:00:00').toLocaleDateString('hu-HU')} napjáig rögzített állás</div></section>
            <section className="card planned-card"><div className="balance-head"><span><SlidersHorizontal size={18}/>Havi terv szerinti maradék</span><CircleHelp size={17}/></div><Ft value={r.closing} className={r.closing.value<0?'negative':'planned-value'}/><p>A hónap nyitó összegéből és havi CF-jéből, a havi családi cél és Örs befizetése után.</p><div className="planned-foot"><span>Havi CF</span><Ft value={r.cf} className={r.cf.value<0?'negative':'positive'}/></div></section></div>
        
        <div className="stats-row"><Stat title="Havi bevétel" value={r.income} icon={<span className="stat-icon positive-bg"><ArrowDownLeft size={18}/></span>} sub="Munka + Egyéb"/><Stat title="Havi kiadás" value={r.expense} icon={<span className="stat-icon warm-bg"><ArrowUpRight size={18}/></span>} sub="Valódi költések"/><Stat title="Havi kiadás napi átlaga" value={r.dailyAverage} icon={<span className="stat-icon neutral-bg"><CalendarDays size={18}/></span>} sub={`${r.elapsedDays} nappal számolva`}/><Stat title="A hónap legdrágább napja" value={r.mostExpensiveAmount} icon={<span className="stat-icon neutral-bg"><BarChart3 size={18}/></span>} sub={r.mostExpensiveDay? new Date(r.mostExpensiveDay+'T12:00:00').toLocaleDateString('hu-HU',{month:'short',day:'numeric'}):'Még nincs kiadás'}/></div>
        <div className="overview-grid"><section className="card budgets-card"><div className="section-title"><div><span className="eyebrow">KÖZÖS HAVI KERETEK</span><h2>Hogyan állunk?</h2></div><Link className="text-link" href={'/tervezes'+query(p)}>Tervezés <ArrowRight size={16}/></Link></div><div className="budget-list">{budgeted.map(c=><BudgetRow key={c.id} category={c}/>)}</div><Link className="card-bottom-link" href={'/honap'+query(p)}>Minden kategória <ArrowRight size={16}/></Link></section>
            <section className="card savings-card"><div className="section-title"><div><span className="eyebrow">LÉPÉSRŐL LÉPÉSRE</span><h2>Havi megtakarítás</h2></div><span className="soft-icon"><PiggyBank size={24}/></span></div><div className="savings-numbers"><div><small>Havi tényleges félretétel</small><Ft value={r.actualSavings}/></div><div><small>Havi cél · {p.settings.savings_rate}%</small><Ft value={r.savingsTarget}/></div></div><div className="progress-track"><span style={{width:`${progress}%`}}/></div><p className="muted">{r.savingsRemaining.value>0?<><Ft value={r.savingsRemaining}/> hiányzik a célhoz.</>:target>0?'A havi megtakarítási cél teljesült.':'Rögzíts bevételt a havi cél kiszámításához.'}</p><button className="button secondary full" onClick={()=>open('saving')}><Plus size={17}/>Félretétel rögzítése</button><div className="child-saving"><span className="child-icon"><Baby size={21}/></span><div><strong>Örs babakötvénye</strong><small>Havi befizetés · külön a családi céltól</small></div><Ft value={r.childSavings}/></div><button className="text-link" onClick={()=>open('child_saving')}>Örs befizetésének rögzítése <ArrowRight size={16}/></button></section>
        </div>
        <section className="card"><h2>A hónap rendszeres tételei</h2><p className="muted">{p.recurring.occurrences.filter(o=>o.paid).length} teljesített, {p.recurring.occurrences.filter(o=>!o.paid).length} még rögzítendő. A sablonok önmagukban nem számítanak tényleges kiadásnak.</p>{p.recurring.occurrences.filter(o=>!o.paid).slice(0,4).map(o=><div className="detail-line" key={`${o.template_id}-${o.due_date}`}><span>{o.name}<small>{o.due_date}</small></span><Ft value={Number(o.payload.amount)}/></div>)}<Link className="text-link" href={'/rendszeres'+query(p)}>Rendszeres tételek kezelése <ArrowRight size={16}/></Link></section><section className="card"><h2>Örs gyermekmegtakarítása</h2><div className="detail-line"><span>Rögzített befektetési érték<small>A legutóbbi értékjelentésekből · {p.investments.through}-ig</small></span>{p.investments.value===null?<span>Még hiányos az értékjelentés</span>:<Ft value={p.investments.value}/>}</div><Link className="text-link" href={'/befektetesek'+query(p)}>Babakötvények és befizetések <ArrowRight size={16}/></Link></section><AccountBalances p={p} compact/><div className="chart-grid"><section className="card"><div className="section-title"><div><span className="eyebrow">NAPRÓL NAPRA</span><h2>A hónap ritmusa</h2></div><span className="chart-key"><span/>Napi kiadás</span></div><DailyChart p={{...p,report:p.scopedReport}}/></section><section className="card"><div className="section-title"><div><span className="eyebrow">A HAVI KÖLTÉSEINK</span><h2>Mire ment el?</h2></div></div><Distribution p={{...p,report:p.scopedReport}}/></section></div>
        <div className="quick-actions"><button className="button secondary" onClick={()=>open('expense')}><ArrowUpRight size={18}/>Kiadás rögzítése</button><button className="button secondary" onClick={()=>open('income')}><ArrowDownLeft size={18}/>Bevétel rögzítése</button></div>
    </>;
}
function BudgetRow({category:c}:{category:CategoryReport}) { const ratio=(c.utilization?.value??0)/100; return <div className="budget-row"><div className="budget-label"><span className="category-dot" style={{background:c.color}}/><strong>{c.name}</strong><span className={c.remaining<0?'negative':'positive'}><Ft value={c.remaining}/></span></div><div className="budget-track"><span style={{width:`${Math.min(100,ratio*100)}%`,background:ratio>1?'var(--danger)':ratio>=.8?'var(--amber)':c.color}}/></div><div className="budget-meta"><span><Ft value={c.spent}/> elköltve</span><span>{c.plan===0?'Nincs megadott keret':<><Ft value={c.plan}/> havi terv</>}</span></div>{c.previous!==0&&<small className="carry-note">Előző hónapról áthozva: <Ft value={c.previous}/></small>}</div>;}
function DailyChart({p}:{p:FinanceProps}) {const max=Math.max(1,...Object.values(p.report.days).map(d=>d.expense));return <div className="daily-chart" role="img" aria-label="Napi kiadások oszlopdiagramja"><div className="chart-scale"><span>{amount(max)} Ft</span><span>0 Ft</span></div><div className="bars">{Object.entries(p.report.days).map(([d,v])=><div className="bar-column" key={d} title={`${d}. nap: ${amount(v.expense)} Ft`}><div className={`bar ${`${p.year}-${String(p.month).padStart(2,'0')}-${String(d).padStart(2,'0')}`===p.today?'today-bar':''}`} style={{height:`${v.expense/max*100}%`}}/>{Number(d)%5===0||d==='1'?<small>{d}</small>:null}</div>)}</div></div>;}
function Distribution({p}:{p:FinanceProps}) {const rows=p.report.categories.filter(c=>c.spent>0).sort((a,b)=>b.spent-a.spent);let offset=0;const segments=rows.map(c=>{const start=offset;offset+=c.spent/Math.max(1,p.report.expense)*100;return `${c.color} ${start}% ${offset}%`;});return <div className="distribution"><div className="donut" style={{background:segments.length?`conic-gradient(${segments.join(',')})`:'var(--line)'}}><div><small>Havi összkiadás</small><Ft value={p.report.expense}/></div></div><div className="distribution-legend">{rows.length?rows.slice(0,5).map(c=><div key={c.id}><span className="category-dot" style={{background:c.color}}/><span>{c.name}</span><Ft value={c.spent}/></div>):<p className="muted">Az első kiadások után itt látod a kategóriák arányát.</p>}</div></div>;}

function EntrySheet({p,entry,close}:{p:FinanceProps;entry:{type:string;tx?:Transaction;date?:string;category?:number;loan?:number};close:()=>void}) {
    const [details,setDetails]=useState(Boolean(entry.tx));
    const [clientId] = useState(() => entry.tx?.client_id ?? createTransactionId());
    const defaultAccount=p.accounts.find(a=>a.id===p.filters.account_id&&a.active&&a.kind!=='snapshot'&&a.kind!=='child')?.id??1;
    const form=useForm({client_id:clientId,type:entry.type,amount:entry.tx?String(entry.tx.amount):'',date:entry.tx?.date??entry.date??p.today,category_id:entry.tx?.category_id??entry.category??null as number|null,subcategory:entry.tx?.subcategory??'',source:entry.tx?.source??(p.filters.person==='Anna'?'Egyéb':'Munka'),note:entry.tx?.note??'',business:entry.tx?.business??false,account_id:entry.tx?.account_id??defaultAccount,target_account_id:entry.tx?.target_account_id??(entry.type==='child_saving'?p.accounts.find(a=>a.kind==='child'&&a.active)?.id??null:null) as number|null,loan_id:entry.tx?.loan_id??entry.loan??null as number|null,person:entry.tx?.person??p.filters.person??'',fee_amount:String(entry.tx?.fee_amount??0)});
    const account=p.accounts.find(a=>a.id===form.data.account_id);
    const effectiveMode=modeAt(account,form.data.date);
    const countedExpense=entry.tx&&entry.tx.type==='expense'&&entry.tx.account_id===form.data.account_id&&entry.tx.date===form.data.date ? !entry.tx.informational : effectiveMode==='detailed';
    const recent = [...new Set(p.transactions.filter(t=>t.type==='expense').map(t=>t.category_id))];
    const categories = [...p.categories].filter(c=>c.active||c.id===entry.tx?.category_id).sort((a,b)=>{const ai=recent.indexOf(a.id),bi=recent.indexOf(b.id);return (ai<0?100:ai)-(bi<0?100:bi)||a.position-b.position;});
    const selected=p.categories.find(c=>c.id===form.data.category_id);
    const accounts=p.accounts.filter(a=>(a.active||a.id===entry.tx?.account_id||a.id===entry.tx?.target_account_id)&&a.kind!=='snapshot');
    const needsTarget=['transfer','child_saving','saving','saving_return'].includes(form.data.type);
    const targets=accounts.filter(a=>a.id!==form.data.account_id&&(form.data.type==='child_saving'?a.kind==='child':['saving','saving_return'].includes(form.data.type)?a.kind==='saving':!['child','saving'].includes(a.kind)));
    const submit=(e:React.FormEvent)=>{e.preventDefault();const next=(e.nativeEvent as SubmitEvent).submitter?.getAttribute('value')==='next';const opts={preserveScroll:true,onSuccess:()=>{if(next&&!entry.tx){form.setData(d=>({...d,client_id:createTransactionId(),amount:'',note:''}));requestAnimationFrame(()=>document.querySelector<HTMLInputElement>('dialog input[aria-label="Összeg"]')?.focus());}else close();}};entry.tx?form.put(`/tetelek/${entry.tx.id}`,opts):form.post('/tetelek',opts);};
    const setType=(type:string)=>form.setData(d=>({...d,type,loan_id:null,target_account_id:type==='child_saving'?p.accounts.find(a=>a.kind==='child'&&a.active)?.id??null:null}));
    return <Sheet title={entry.tx?'Tétel szerkesztése':'Gyors rögzítés'} close={close}><form onSubmit={submit} className="entry-form"><div className="sheet-scroll"><p className="muted">Tétel dátuma: {huDate(form.data.date)}</p><div className="segmented entry-type"><button type="button" className={form.data.type==='expense'?'active':''} onClick={()=>setType('expense')}>Kiadás</button><button type="button" className={form.data.type==='income'?'active':''} onClick={()=>setType('income')}>Bevétel</button><button type="button" className={form.data.type==='transfer'?'active':''} onClick={()=>setType('transfer')}>Átvezetés</button><button type="button" className={['saving','saving_return','child_saving'].includes(form.data.type)?'active':''} onClick={()=>setType('saving')}>Félretétel</button></div>
        {['saving','saving_return','child_saving'].includes(form.data.type)&&<label>Megtakarítás típusa<select value={form.data.type} onChange={e=>setType(e.target.value)}><option value="saving">Családi félretétel</option><option value="child_saving">Örs babakötvény-befizetése</option><option value="saving_return">Családi megtakarítás visszavétele</option></select></label>}
        <label className="amount-label">Összeg<div className="amount-input"><MoneyInput aria-label="Összeg" autoFocus placeholder="0" value={form.data.amount} onValueChange={raw=>form.setData('amount',raw)} required/><span>Ft</span></div><ErrorText error={form.errors.amount}/></label>
        <label>{form.data.type==='saving_return'?'Fogadó számla':'Számla'}<select aria-label="Rögzítés számlája" value={form.data.account_id} onChange={e=>form.setData(d=>({...d,account_id:Number(e.target.value),person:''}))}>{accounts.filter(a=>a.kind!=='child').map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select><ErrorText error={form.errors.account_id}/></label>
        {needsTarget&&<label>{form.data.type==='saving_return'?'Visszavétel forrása':'Célszámla'}<select aria-label="Célszámla" value={form.data.target_account_id??''} onChange={e=>form.setData('target_account_id',Number(e.target.value)||null)} required={['transfer','child_saving'].includes(form.data.type)}><option value="">{['saving','saving_return'].includes(form.data.type)?'Külső, külön számla nélkül':'Válassz célszámlát'}</option>{targets.map(a=><option value={a.id} key={a.id}>{a.name}</option>)}</select><ErrorText error={form.errors.target_account_id}/></label>}
        {form.data.type==='transfer'&&<><p className="notice">Egyszer rögzítsd: a forrásszámlából levonjuk, a célszámlához hozzáadjuk. Az alszámlás fedezet nem törlesztés; zsebpénzes vagy összevont cél esetén a feltöltés egyszer családi kiadás.</p><label>Átutalási díj (Ft)<MoneyInput aria-label="Átutalási díj (Ft)" value={form.data.fee_amount} onValueChange={raw=>form.setData('fee_amount',raw)} required/><small>Ha volt díj, a forrásszámlán külön banki költségként számít.</small><ErrorText error={form.errors.fee_amount}/></label></>}
        {form.data.type==='expense'&&(countedExpense?<><div className="label-row"><strong>Kategória</strong><small>Legutóbb használtak elöl</small></div><div className="category-choices">{categories.map(c=><button type="button" key={c.id} className={form.data.category_id===c.id?'chosen':''} onClick={()=>form.setData(d=>({...d,category_id:c.id,subcategory:'',loan_id:c.id===13?d.loan_id:null}))}><span style={{background:c.color}}/>{c.name}{form.data.category_id===c.id&&<Check size={15}/>}</button>)}</div><ErrorText error={form.errors.category_id}/>{selected?.id===19&&<p className="notice">Ez felosztandó készpénz. A valódi költési kategóriát később itt módosíthatod.</p>}</>:<p className="notice">kp · Csak az egyenleg csökken. A feltöltés már családi kiadásként szerepel, ezt nem számoljuk újra.</p>)}
        {(form.data.type==='expense'&&form.data.category_id===13&&countedExpense||form.data.type==='transfer')&&<label>{form.data.type==='transfer'?'Hitelhez tartozó fedezet (opcionális)':'Melyik hitel törlesztése?'}<select aria-label={form.data.type==='transfer'?'Hitelhez tartozó fedezet (opcionális)':'Melyik hitel törlesztése?'} value={form.data.loan_id??''} onChange={e=>form.setData('loan_id',Number(e.target.value)||null)}><option value="">Még nincs hozzárendelve</option>{p.loans.map(l=><option key={l.id} value={l.id}>{l.name}{l.closed_date&&l.closed_date<=p.today?' · Lezárt':''}</option>)}</select><ErrorText error={form.errors.loan_id}/></label>}
        {form.data.type==='income'&&<><label>Bevétel forrása<select value={form.data.source} onChange={e=>form.setData('source',e.target.value)}><option>Munka</option><option>Egyéb</option></select><ErrorText error={form.errors.source}/><small>Anna hozzájárulása: főszámla, Egyéb, személy: Anna. SZÉP-jóváírás: Munka, külön kötött egyenleg.</small></label><label>Bevételhez tartozó személy<select value={form.data.person} onChange={e=>form.setData(d=>({...d,person:e.target.value,...(d.type==='income'&&e.target.value==='Anna'?{source:'Egyéb',account_id:1}:{})}))}><option value="">A számla tulajdonosa</option>{p.people.map(person=><option key={person}>{person}</option>)}</select><ErrorText error={form.errors.person}/></label></>}
        <button type="button" className="details-toggle" aria-expanded={details} onClick={()=>setDetails(!details)}><SlidersHorizontal size={16}/>Dátum, megjegyzés és részletek<ChevronRight size={16}/></button>
        {details&&<div className="entry-details"><label>Dátum<input type="date" value={form.data.date} onChange={e=>form.setData('date',e.target.value)} required/><ErrorText error={form.errors.date}/></label>{form.data.type==='expense'&&selected&&countedExpense&&<label>Alkategória<select value={form.data.subcategory} onChange={e=>form.setData('subcategory',e.target.value)}><option value="">Nincs külön alkategória</option>{selected.subcategories.map(s=><option key={s}>{s}</option>)}</select><ErrorText error={form.errors.subcategory}/></label>}{form.data.type!=='income'&&<label>Érintett személy<select value={form.data.person} onChange={e=>form.setData(d=>({...d,person:e.target.value,...(d.type==='income'&&e.target.value==='Anna'?{source:'Egyéb',account_id:1}:{})}))}><option value="">A számla tulajdonosa</option>{p.people.map(person=><option key={person}>{person}</option>)}</select><ErrorText error={form.errors.person}/></label>}<label>Megjegyzés<textarea value={form.data.note} onChange={e=>form.setData('note',e.target.value)} placeholder="Opcionális megjegyzés" maxLength={2000}/></label><label className="checkbox-label"><input type="checkbox" checked={form.data.business} onChange={e=>form.setData('business',e.target.checked)}/>Üzleti tétel</label></div>}</div>
        <div className="sheet-footer">{!entry.tx&&<button type="submit" value="next" className="button secondary full next-entry" disabled={form.processing||!form.data.amount||(form.data.type==='expense'&&countedExpense&&!form.data.category_id)}>Mentés és következő<Plus size={18}/></button>}<button type="submit" className="button primary full" disabled={form.processing||!form.data.amount||(form.data.type==='expense'&&countedExpense&&!form.data.category_id)}>{form.processing?'Mentés…':entry.tx?'Módosítás mentése':'Tétel mentése'}<Check size={18}/></button></div></form></Sheet>;
}

function MonthView({p,open,edit}:{p:FinanceProps;open:(type?:string,date?:string,category?:number)=>void;edit:(tx:Transaction)=>void}) {
    const [day,setDay]=useState<number|null>(null);const [table,setTable]=useState(window.matchMedia('(min-width: 1024px)').matches);const [search,setSearch]=useState('');
    useEffect(()=>{const media=window.matchMedia('(min-width: 1024px)');const onChange=()=>setTable(media.matches);media.addEventListener('change',onChange);return()=>media.removeEventListener('change',onChange);},[]);
    const date=(d:number)=>`${p.year}-${String(p.month).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
    const categories=p.report.categories.filter(c=>c.active||c.spent||c.plan);
    const rows=p.transactions.filter(t=>!search||`${t.note??''} ${p.categories.find(c=>c.id===t.category_id)?.name??''} ${t.amount} ${t.subcategory??''}`.toLocaleLowerCase('hu').includes(search.toLocaleLowerCase('hu')));
    const note=useForm({date:'',note:''});
    useEffect(()=>{if(day!==null)note.setData({date:date(day),note:p.notes[date(day)]??''});},[day,p.month,p.year]);
    return <><MonthCompletion p={p}/><div className="month-summary"><Stat title="Havi kiadás" value={p.report.expense}/><Stat title="Havi bevétel" value={p.report.income}/><Stat title="Havi CF" value={p.report.cf}/></div><div className="section-title"><h2>A hónap napjai</h2><button className={`button compact ${table?'primary':'secondary'}`} onClick={()=>setTable(!table)}><LayoutGrid size={16}/>{table?'Napi lista':'Táblázat'}</button></div><label className="search-box"><Search size={18}/><input aria-label="Keresés a havi tételekben" placeholder="Keresés a tételekben…" value={search} onChange={e=>setSearch(e.target.value)}/></label>
    {search&&<div className="card"><h3>Keresési találatok · {rows.length}</h3>{rows.map(tx=><TransactionRow key={tx.id} tx={tx} p={p} edit={edit}/>)}{rows.length===0&&<p className="muted">Nincs ilyen tétel ebben a hónapban.</p>}</div>}
    {!search&&!table&&<div className="days-list">{Object.entries(p.scopedReport.days).map(([d,total])=>{const iso=date(Number(d));const count=p.transactions.filter(t=>t.date===iso).length;return <button key={d} className={`day-row ${iso===p.today?'today':''}`} onClick={()=>setDay(Number(d))}><span className="day-number">{d}</span><span className="day-label"><strong>{new Date(iso+'T12:00:00').toLocaleDateString('hu-HU',{weekday:'long'})}</strong><small>{count?`${count} tétel`: 'Nincs rögzített tétel'}{p.notes[iso]?' · Megjegyzés':''}{iso===p.today?' · Ma':''}</small></span><Ft value={total.expense}/><ChevronRight size={17}/></button>;})}</div>}
    {!search&&table&&<div className="table-scroll" tabIndex={0} aria-label="Napi kategória-táblázat, vízszintesen görgethető"><table><thead><tr><th>Nap</th>{categories.map(c=><th key={c.id}>{c.name}</th>)}<th>Napi kiadás</th><th>Napi bevétel · Munka</th><th>Napi bevétel · Egyéb</th></tr></thead><tbody>{Object.entries(p.scopedReport.days).map(([d,total])=><tr key={d}><th><button onClick={()=>setDay(Number(d))}>{d}. {new Date(date(Number(d))+'T12:00:00').toLocaleDateString('hu-HU',{weekday:'short'})}</button></th>{categories.map(c=>{const value=p.familyTransactions.filter(t=>t.date===date(Number(d))&&t.type==='expense'&&t.category_id===c.id).reduce((a,t)=>a+t.amount,0);return <td key={c.id}><button aria-label={`${d}. nap, ${c.name}: ${value} Ft`} onClick={()=>{const items=p.familyTransactions.filter(t=>t.date===date(Number(d))&&t.type==='expense'&&t.category_id===c.id);if(items.length===1)edit(p.transactions.find(t=>t.id===items[0].id)!);else if(items.length>1)setDay(Number(d));else open('expense',date(Number(d)),c.id);}}>{value?amount(value):'–'}</button></td>;})}<td><Ft value={total.expense}/></td>{['Munka','Egyéb'].map(source=><td key={source}>{amount(p.familyTransactions.filter(t=>t.date===date(Number(d))&&t.type==='income'&&t.source===source).reduce((a,t)=>a+t.amount,0))}</td>)}</tr>)}</tbody><tfoot>{['spent','plan','remaining'].map((key,i)=><tr key={key}><th>{[p.filters.account_id||p.filters.person?'Szűrt havi kiadás':'Havi összkiadás','Családi havi terv','Családi maradék'][i]}</th>{categories.map(c=><td key={c.id} className={key==='remaining'&&c.remaining<0?'negative':''}>{amount(key==='spent'?(p.scopedReport.categories.find(row=>row.id===c.id)?.spent??0):c[key as 'plan'|'remaining'])}</td>)}<td colSpan={3}/></tr>)}</tfoot></table></div>}
    {p.transactions.some(t=>t.type==='transfer'||t.informational)&&<section className="card movement-list"><h2>Havi átvezetések és belső költések</h2><p className="muted">A vásárlási rácsban csak a családi elszámolásba tartozó kiadás szerepel. Az átvezetés mindkét számla egyenlegét módosítja.</p>{p.transactions.filter(t=>t.type==='transfer'||t.informational).map(tx=><TransactionRow key={tx.id} tx={tx} p={p} edit={edit}/>)}</section>}
    <section className="card month-categories"><div className="section-title"><div><span className="eyebrow">CSALÁDI KERETEK · KATEGÓRIÁNKÉNT</span><h2>Ennyit költhetek még a hónapban</h2></div><Link className="text-link" href={'/tervezes'+query(p)}>Tervek<ArrowRight size={16}/></Link></div><div className="category-budget-grid">{categories.map(c=><div className="category-budget" key={c.id}><BudgetRow category={c}/><p className="difference"><span>Havi tény − terv</span><Ft value={c.difference} className={c.difference>0?'negative':'positive'}/><span>{c.differencePercent?`${c.differencePercent.text}%`:'Keret nélkül'}</span></p></div>)}</div></section>
    {(p.report.actualSavings!==0||p.report.childSavings!==0)&&<div className="card"><h2>A hónap külön pénzmozgásai</h2><div className="detail-line"><span>Havi családi félretétel</span><Ft value={p.report.actualSavings}/></div><div className="detail-line"><span>Örs havi befizetése</span><Ft value={p.report.childSavings}/></div></div>}
    {day!==null&&<Sheet title={`${months[p.month-1]} ${day}. · ${new Date(date(day)+'T12:00:00').toLocaleDateString('hu-HU',{weekday:'long'})}`} close={()=>setDay(null)}><div className="sheet-scroll day-sheet">{p.transactions.filter(t=>t.date===date(day!)).map(t=><TransactionRow key={t.id} tx={t} p={p} edit={tx=>{setDay(null);edit(tx);}}/>)}{!p.transactions.some(t=>t.date===date(day!))&&<Empty title="Még üres ez a nap." text="Rögzíts egy kiadást vagy bevételt, és itt megjelenik."/>}<div className="quick-actions"><button className="button secondary" onClick={()=>{const iso=date(day!);setDay(null);open('expense',iso);}}><Plus size={17}/>Kiadás</button><button className="button secondary" onClick={()=>{const iso=date(day!);setDay(null);open('income',iso);}}><Plus size={17}/>Bevétel</button></div><form onSubmit={e=>{e.preventDefault();note.post('/napi-megjegyzes',{preserveScroll:true});}}><label>Napi megjegyzés<textarea value={note.data.note} onChange={e=>note.setData('note',e.target.value)} placeholder="Mi történt ma?" maxLength={2000}/></label><button className="button secondary full" disabled={note.processing}>Megjegyzés mentése</button></form></div></Sheet>}
    </>;
}
function TransactionRow({tx,p,edit}:{tx:Transaction;p:FinanceProps;edit:(tx:Transaction)=>void}) { const category=p.categories.find(c=>c.id===tx.category_id);return <div className="transaction-row"><span className="tx-symbol" style={{color:category?.color}}>{tx.type==='expense'?<ArrowUpRight size={20}/>:tx.type==='income'?<ArrowDownLeft size={20}/>:<PiggyBank size={20}/>}</span><div className="transaction-copy"><strong>{tx.informational?'kp · belső költés':tx.type==='transfer'?'Átvezetés':category?.name??labels[tx.type]??tx.type}</strong><small>{p.accounts.find(a=>a.id===tx.account_id)?.name}{tx.target_account_id?` → ${p.accounts.find(a=>a.id===tx.target_account_id)?.name}`:''} · {tx.person}</small>{tx.fee_amount>0&&<small>Banki díj: <Ft value={tx.fee_amount}/></small>}{tx.loan_id&&<small>{p.loans.find(l=>l.id===tx.loan_id)?.name} · {tx.type==='transfer'?'Fedezet':'Törlesztés'}</small>}<small>{tx.note||tx.subcategory||tx.source||tx.date}{tx.business?' · Üzleti':''}</small></div><Ft value={tx.amount} className={tx.type==='income'?'positive':''}/><button className="icon-button" aria-label="Tétel szerkesztése" onClick={()=>edit(tx)}><Pencil size={16}/></button><button className="icon-button" aria-label="Tétel törlése" onClick={()=>{if(confirm('Törlöd ezt a tételt? A törlés visszavonható.'))router.delete(`/tetelek/${tx.id}`,{preserveScroll:true});}}><Trash2 size={16}/></button></div>; }

function Plans({p}:{p:FinanceProps}) {
    const [base,setBase]=useState(false);
    const initial=()=>Object.fromEntries(p.categories.map(c=>[String(c.id),String(base?c.default_amount:p.report.categories.find(r=>r.id===c.id)?.plan??0)]));
    const form=useForm({year:p.year,month:p.month,mode:'monthly',amounts:initial() as Record<string,string>});
    useEffect(()=>{form.setData({year:p.year,month:p.month,mode:base?'base':'monthly',amounts:initial()});},[base,p.month,p.year,p.categories]);
    const [copying,setCopying]=useState(false);
    return <><PlanSuggestion p={p} apply={(id,value)=>form.setData('amounts',{...form.data.amounts,[id]:value})} base={base}/><div className="plans-toolbar"><div className="segmented"><button className={!base?'active':''} onClick={()=>setBase(false)}>Havi terv</button><button className={base?'active':''} onClick={()=>setBase(true)}>Havi alapterv</button></div>{!base&&<button className="button secondary compact" disabled={copying} onClick={()=>{setCopying(true);router.post('/tervek',{year:p.year,month:p.month,mode:'copy',amounts:form.data.amounts},{preserveScroll:true,onFinish:()=>setCopying(false)});}}><Copy size={16}/>Előző hónap másolása</button>}</div><p className="notice">{base?'A havi alapterv összegei minden következő hónapra külön érvényesek. A korábbi hónapok és a kézzel felülírt keretek megmaradnak.':'A kiválasztott hónap kerete az egész családé. A kategória maradéka az átvitel beállítása szerint folytatódik a következő hónapban.'}</p><form onSubmit={e=>{e.preventDefault();form.post('/tervek',{preserveScroll:true});}}><div className="plan-grid">{p.categories.filter(c=>c.active||c.default_amount||p.report.categories.find(r=>r.id===c.id)?.spent).map(c=><label className="plan-card card" key={c.id}><span className="plan-name"><span className="category-dot" style={{background:c.color}}/>{c.name}</span><div className="plan-amount"><MoneyInput aria-label={`${c.name} kerete`} value={form.data.amounts[c.id]??'0'} onValueChange={raw=>form.setData('amounts',{...form.data.amounts,[c.id]:raw})} required/><span>Ft</span></div><small>{c.carryover?'Maradék átvitele bekapcsolva':'Havonta új keret'}</small><ErrorText error={form.errors[`amounts.${c.id}` as keyof typeof form.errors]}/></label>)}</div><div className="save-bar"><span>Összes havi keret: <Ft value={Object.values(form.data.amounts).reduce((a,b)=>a+Number(b||0),0)}/></span><button className="button primary" disabled={form.processing}><Check size={18}/>{base?'Alapterv mentése':'Havi terv mentése'}</button></div></form></>;
}

function MonthCompletion({p}:{p:FinanceProps}) {
    const past=`${p.year}-${String(p.month).padStart(2,'0')}`<p.today.slice(0,7);
    if(!past)return null;
    return <section className="card month-completion"><h2>A havi rögzítés teljessége</h2><p className="muted">{p.monthComplete?'A hónapot teljesnek jelölted; felhasználható a háromhavi tervjavaslatban.':'Ellenőrizd, hogy minden költés és bevétel szerepel. Csak ezután jelöld teljesnek a hónapot. Pénzmozgás módosítása után újra ellenőrizni kell.'}</p><button className="button secondary" onClick={()=>router.post('/honap-teljes',{year:p.year,month:p.month,complete:!p.monthComplete},{preserveScroll:true})}>{p.monthComplete?'Még nincs minden rögzítve':'A hónap rögzítése teljes'}</button></section>;
}

function PlanSuggestion({p,apply,base}:{p:FinanceProps;apply:(id:string,value:string)=>void;base:boolean}) {
    return <details className="card plan-suggestion"><summary>Havi tervjavaslat · az előző három hónap átlaga</summary><p className="muted">Időszak: {p.suggestions.periods.join(', ')}. A javaslat közös családi keret; elfogadása után még mentsd el a tervet.</p>{p.suggestions.missing.length?<><p className="notice">Még nincs teljesen rögzítve: {p.suggestions.missing.join(', ')}. Ezeket előbb a Havi nézetben ellenőrizd és jelöld teljesnek. Üres hónapot nem tekintünk automatikusan nulla költésűnek.</p><Link className="text-link" href={`/honap?year=${p.suggestions.missing[0]?.slice(0,4)}&month=${Number(p.suggestions.missing[0]?.slice(5))}`}>Havi rögzítés ellenőrzése<ArrowRight size={16}/></Link></>:<><p className="muted">A tört forintos átlag pontosan látszik. Ilyenkor te döntesz az egész forintos keretről, az app nem kerekít.</p>{p.categories.filter(c=>c.active).map(c=>{const suggestion=p.suggestions.amounts[c.id];return suggestion&&<div className="suggestion-row" key={c.id}><strong>{c.name}</strong><Ft value={suggestion}/>{suggestion.denominator==='1'?<button type="button" className="button secondary compact" disabled={base} onClick={()=>apply(String(c.id),suggestion.numerator)}>Havi tervhez</button>:<small>Adj meg saját egész keretet.</small>}</div>;})}{base&&<p className="notice">Válts a Havi tervre a javaslat átvételéhez.</p>}</>}</details>;
}

function Settings({p,toggleTheme,dark}:{p:FinanceProps;toggleTheme:()=>void;dark:boolean}) {
    const form=useForm({year:p.year,opening_amount:String(p.settings.opening_amount),savings_rate:p.settings.savings_rate,opening_balance:String(p.account.opening_balance),opening_date:p.account.opening_date});
    useEffect(()=>{form.setData({year:p.year,opening_amount:String(p.settings.opening_amount),savings_rate:p.settings.savings_rate,opening_balance:String(p.account.opening_balance),opening_date:p.account.opening_date});},[p.year]);
    const [editing,setEditing]=useState<Category|'new'|null>(null);
    const reorder=(i:number,delta:number)=>{const ids=p.categories.map(c=>c.id);[ids[i],ids[i+delta]]=[ids[i+delta],ids[i]];router.post('/kategoriak/sorrend',{ids},{preserveScroll:true});};
    return <><section className="card"><div className="section-title"><div><span className="eyebrow">A SAJÁT SZÁMAID</span><h2>Kezdőadatok · {p.year}</h2></div><Wallet size={22}/></div><form onSubmit={e=>{e.preventDefault();form.post('/beallitasok',{preserveScroll:true});}}><div className="form-grid"><label>Terv szerinti éves nyitó összeg<MoneyInput value={form.data.opening_amount} onValueChange={raw=>form.setData('opening_amount',raw)} allowNegative required/><small>A(z) {p.year}. év január 1-jei tervezett nyitó összege. A havi maradék innen folytatódik hónapról hónapra.</small><ErrorText error={form.errors.opening_amount}/></label><label>Havi családi megtakarítási cél (%)<input type="number" min={0} max={100} step="0.0001" inputMode="decimal" value={form.data.savings_rate} onChange={e=>form.setData('savings_rate',e.target.value)}/><small>Minden hónap saját bevételének ennyi százaléka a havi cél. Ez az arány a(z) {p.year}. év mind a 12 hónapjára érvényes. Örs befizetése külön kezelt.</small><ErrorText error={form.errors.savings_rate}/></label><label>{p.account.name} valós nyitóegyenlege<MoneyInput value={form.data.opening_balance} onValueChange={raw=>form.setData('opening_balance',raw)} allowNegative required/><small>A lent megadott dátumhoz tartozó valós számlaegyenleg. Ez egy adott napi egyenleg, nem havi vagy éves keret; az évválasztó nem módosítja.</small><ErrorText error={form.errors.opening_balance}/></label><label>A számla nyitóegyenlegének dátuma<input type="date" value={form.data.opening_date} onChange={e=>form.setData('opening_date',e.target.value)}/><small>Az ettől a naptól rögzített mozgások számítanak hozzá.</small><ErrorText error={form.errors.opening_date}/></label></div><button className="button primary" disabled={form.processing}><Check size={18}/>Kezdőadatok mentése</button></form></section>
    <ReminderSettings p={p.push}/>
    {p.systemStatus&&<SystemStatus status={p.systemStatus}/>}
    <DataTools p={p}/>
    <section className="card category-settings"><div className="section-title"><div><span className="eyebrow">EGYETLEN KÖZÖS LISTA</span><h2>Kategóriák</h2></div><button className="button secondary compact" onClick={()=>setEditing('new')}><Plus size={17}/>Új</button></div><p className="muted">A kikapcsolt kategóriák régi tételei megmaradnak. Az átvitel a pozitív és negatív maradékot is továbbviszi az éven belül.</p>{p.categories.map((c,i)=><div className={`category-setting-row ${c.active?'':'inactive'}`} key={c.id}><span className="category-dot" style={{background:c.color}}/><div className="category-setting-copy"><strong>{c.name}</strong><small>{c.active?'Aktív':'Kikapcsolva'} · {c.carryover?'Átvitel be':'Átvitel ki'}</small></div><button className="icon-button" disabled={i===0} aria-label={`${c.name} feljebb`} onClick={()=>reorder(i,-1)}><ArrowUp size={16}/></button><button className="icon-button" disabled={i===p.categories.length-1} aria-label={`${c.name} lejjebb`} onClick={()=>reorder(i,1)}><ArrowDown size={16}/></button><button className="icon-button" aria-label={`${c.name} szerkesztése`} onClick={()=>setEditing(c)}><Pencil size={17}/></button></div>)}</section>
    <section className="card"><h2>Megjelenés és belépés</h2><div className="quick-actions"><button className="button secondary" onClick={toggleTheme}>{dark?<Sun size={18}/>:<Moon size={18}/>} {dark?'Világos téma':'Sötét téma'}</button><button className="button secondary" onClick={()=>router.post('/kilepes')}><LogOut size={18}/>Kilépés</button></div></section>
    {editing&&<CategorySheet category={editing==='new'?undefined:editing} close={()=>setEditing(null)}/>}
    </>;
}
function CategorySheet({category:c,close}:{category?:Category;close:()=>void}) {
    const form=useForm({name:c?.name??'',color:c?.color??'#367B5D',active:c?.active??true,carryover:c?.carryover??true,subcategories:c?.subcategories??[] as string[]});
    const [subs,setSubs]=useState(c?.subcategories.join('\n')??'');
    return <Sheet title={c?'Kategória szerkesztése':'Új kategória'} close={close}><form className="category-form" onSubmit={e=>{e.preventDefault();form.transform(d=>({...d,subcategories:subs.split('\n').map(s=>s.trim()).filter(Boolean)}));const opts={preserveScroll:true,onSuccess:close};c?form.put(`/kategoriak/${c.id}`,opts):form.post('/kategoriak',opts);}}><div className="sheet-scroll"><label>Név<input value={form.data.name} onChange={e=>form.setData('name',e.target.value)} required maxLength={100}/><ErrorText error={form.errors.name}/></label><label>Szín<input className="color-input" type="color" value={form.data.color} onChange={e=>form.setData('color',e.target.value)}/></label><label>Alkategóriák<textarea rows={5} value={subs} onChange={e=>setSubs(e.target.value)} placeholder="Minden alkategória külön sorba"/><small>Minden alkategóriát külön sorba írj.</small><ErrorText error={form.errors.subcategories}/></label><label className="checkbox-label"><input type="checkbox" checked={form.data.active} onChange={e=>form.setData('active',e.target.checked)}/>Aktív kategória</label><label className="checkbox-label"><input type="checkbox" checked={form.data.carryover} onChange={e=>form.setData('carryover',e.target.checked)}/>Maradék átvitele a következő hónapra</label></div><div className="sheet-footer"><button className="button primary full" disabled={form.processing}><Check size={18}/>Kategória mentése</button></div></form></Sheet>;
}
